from collections import defaultdict

input_grid = [
    [3, 3, 3, 3, 3, 3] for _ in range(25)
]

input_grid[20] = [3, 3, 3, 3, 4, 3]
input_grid[21] = [3, 3, 9, 4, 3, 3]
input_grid[22] = [3, 3, 1, 9, 3, 3]
input_grid[23] = [3, 1, 3, 3, 3, 3]

value_pos = defaultdict(list)
for r, row in enumerate(input_grid):
    for c, val in enumerate(row):
        if val != 3:
            value_pos[val].append((r, c))

print("Values and their positions:")
for val, pos_list in sorted(value_pos.items()):
    print(f"  {val}: {pos_list}")

print("\nDC calculations:")
for val in sorted(value_pos.keys()):
    sorted_pos = sorted(value_pos[val])
    if len(sorted_pos) >= 2:
        dc = sorted_pos[1][1] - sorted_pos[0][1]
        print(f"  {val}: dc = {dc}")

# Compute extensions
print("\nExtensions:")
output_grid = [[3 for _ in range(6)] for _ in range(25)]

for val in sorted(value_pos.keys()):
    sorted_pos = sorted(value_pos[val])
    if len(sorted_pos) >= 2:
        dc = sorted_pos[1][1] - sorted_pos[0][1]
        # Copy all existing positions
        for r, c in sorted_pos:
            output_grid[r][c] = val
        # Extend from last position
        last_r, last_c = sorted_pos[-1]
        for i in range(1, 25 - last_r + 1):  # Stay within bounds (25 rows max)
            r = last_r + i
            c = last_c + dc * i
            if r < 25 and 0 <= c < 6:
                output_grid[r][c] = val
            elif r < 25 or (0 <= c < 6):
                # Partially out of bounds, stop
                break

print("\nOutput grid:")
for r in range(25):
    print(" ".join(str(x) for x in output_grid[r]))

